package name.boyle.chris.sgtpuzzles.parity

import name.boyle.chris.sgtpuzzles.engine.SgtpSave
import org.junit.Assert.assertEquals
import org.junit.Assert.assertTrue
import org.junit.Test
import java.io.File

/**
 * Level: strict. The `.sgtp` cross-compatibility corpus.
 *
 * Every file is parsed by the Kotlin engine and written back. The
 * oracle must accept both the original and the written text and report
 * the same game. This proves both directions: Kotlin reads what C
 * writes, and C reads what Kotlin writes.
 *
 * The corpus is generated by `tools/gen-saves.sh`.
 */
class SaveParityTest {

    private val testdata = File(
        System.getProperty("testdata") ?: error("testdata system property is not set"),
    )
    private val saves = File(testdata, "saves")

    @Test
    fun `every corpus save round-trips and reloads`() = OracleClient().use { oracle ->
        val files = saves.walkTopDown()
            .filter { it.isFile && it.extension == "sgtp" }
            .sorted()
            .toList()
        assertTrue("no save corpus under ${saves.path}", files.isNotEmpty())

        for (file in files) {
            val text = file.readText()
            val save = SgtpSave.parse(text)
            val written = save.serialise()
            assertEquals("canonical text of ${file.path}", text, written)

            val original = oracle.id(text)
            val reloaded = oracle.id(written)
            assertEquals("id of ${file.path}", original.id, reloaded.id)
            assertEquals("game of ${file.path}", original.game, reloaded.game)
            assertEquals("status of ${file.path}", original.status, reloaded.status)
        }
    }

    @Test
    fun `the corpus covers every preset and known upstream defect`() = OracleClient().use { oracle ->
        val expected = sortedSetOf<String>()

        for (game in oracle.games().sorted()) {
            val presets = linkedSetOf("")
            oracle.presets(game).mapTo(presets) { it.params }

            for (params in presets.sorted()) {
                val state = oracle.newGame(game, params, GenGoldens.SEED)
                val reload = try {
                    oracle.id(state.state)
                } catch (e: OracleException) {
                    null
                }
                if (reload == null) {
                    /*
                     * Upstream saves `5x5random` with long-term params
                     * that upstream itself rejects. It is not a format
                     * difference and not our bug, so the corpus cannot
                     * contain it. Pin the exclusion rather than hiding
                     * it: if upstream fixes the preset, this fails.
                     */
                    assertEquals("pegs", game)
                    assertEquals("5x5random", params)
                    continue
                }
                assertEquals("reload id of $game '$params'", state.id, reload.id)
                expected += SaveNames.initialPath(game, params)
            }
        }

        val actual = File(saves, "initial").walkTopDown()
            .filter { it.isFile && it.extension == "sgtp" }
            .map { it.relativeTo(saves).invariantSeparatorsPath }
            .toSortedSet()

        assertEquals("the save corpus must cover every readable preset", expected, actual)
    }

    @Test
    fun `initial saves are initial states`() {
        val initial = File(saves, "initial")
        for (file in initial.walkTopDown().filter { it.isFile && it.extension == "sgtp" }) {
            val save = SgtpSave.parse(file.readText())
            assertTrue("no GAME in ${file.path}", !save.value("GAME").isNullOrEmpty())
            assertEquals("NSTATES in ${file.path}", "1", save.value("NSTATES"))
            assertEquals("STATEPOS in ${file.path}", "1", save.value("STATEPOS"))
            assertTrue("no moves in an initial save: ${file.path}", save.values("MOVE").isEmpty())
        }
    }

    @Test
    fun `the case saves pin MOVE, undo, and SOLVE`() {
        val moves = SgtpSave.parse(File(saves, "cases/fifteen-4x4-moves.sgtp").readText())
        assertEquals("MOVE records", 4, moves.values("MOVE").size)
        assertEquals("state count", "5", moves.value("NSTATES"))
        assertEquals("position", "5", moves.value("STATEPOS"))

        val undo = SgtpSave.parse(File(saves, "cases/fifteen-4x4-undo.sgtp").readText())
        assertTrue(
            "an undone state keeps the redo history",
            undo.value("STATEPOS")!!.toInt() < undo.value("NSTATES")!!.toInt(),
        )

        val solve = SgtpSave.parse(File(saves, "cases/fifteen-4x4-solve.sgtp").readText())
        assertEquals("SOLVE record", listOf("S"), solve.values("SOLVE"))
    }
}
